import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;import java.util.*;
@WebServlet("/sos") public class SOSServlet extends HttpServlet{
 protected void doPost(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{if(!Security.requireUser(q,p))return;Double lat=num(q.getParameter("latitude")),lng=num(q.getParameter("longitude")),acc=num(q.getParameter("accuracy"));if((lat==null)!=(lng==null)||(lat!=null&&(lat < -90||lat>90||lng < -180||lng>180))){Security.json(p,400,"{\"status\":\"error\",\"message\":\"Invalid location data.\"}");return;}int id=Security.userId(q);if(!new SOSAlertDAO().createAlert(new SOSAlert(id,lat,lng,"ACTIVE"))){Security.json(p,503,"{\"status\":\"error\",\"message\":\"SOS event could not be saved. No dispatch was attempted.\"}");return;}List<Map<String,String>> results=new ArrayList<>();for(TrustedContact c:new TrustedContactDAO().getTrustedContacts(id)){Map<String,String> row=new LinkedHashMap<>();row.put("contactName",c.getContactName());try{String state=TwilioCallService.makeCall(c.getPhoneNumber());row.put("status","queued".equalsIgnoreCase(state)?"QUEUED":"PROVIDER_"+state.toUpperCase(Locale.ROOT));}catch(Exception e){row.put("status","FAILED");}results.add(row);}boolean any=results.stream().anyMatch(x->x.get("status").startsWith("QUEUED")||x.get("status").startsWith("PROVIDER_"));Security.json(p,200,"{\"status\":\"success\",\"message\":\"SOS event saved. Provider submission results are shown below; queued does not confirm delivery.\",\"calls\":"+toJson(results)+"}");}
 private Double num(String x){try{return x==null||x.isBlank()?null:Double.valueOf(x);}catch(Exception e){return null;}}
 private String toJson(List<Map<String,String>> rows){StringBuilder b=new StringBuilder("[");for(int i=0;i<rows.size();i++){if(i>0)b.append(',');Map<String,String> x=rows.get(i);b.append("{\"contactName\":").append(Security.quote(x.get("contactName"))).append(",\"status\":").append(Security.quote(x.get("status"))).append('}');}return b.append(']').toString();}
}
